{s:0:\"\";a:1:{s:4:\"type\";s:4:\"html\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"author\";a:1:{i:0;a:6:{s:4:\"data\";s:46:\"\n            \n                                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"name\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Julio Potier\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:6:\"source\";a:1:{i:0;a:6:{s:4:\"data\";s:67:\"\n                    \n                            \n                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:2:{s:2:\"id\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://21douze.fr/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"21douze\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}i:9;a:6:{s:4:\"data\";s:70:\"\n    \n    \n    \n    \n    \n    \n    \n            \n                \n    \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:9:{s:2:\"id\";a:1:{i:0;a:5:{s:4:\"data\";s:140:\"https://jeanbaptisteaudras.com/2024/10/valoriser-les-contributions-des-entreprises-dans-lecosysteme-wordpress-et-si-on-sinspirait-de-drupal/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:118:\"Valoriser les contributions des entreprises dans l’écosystème WordPress : et si on s’inspirait de… Drupal ?\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:4:\"type\";s:4:\"html\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:2:{s:4:\"href\";s:140:\"https://jeanbaptisteaudras.com/2024/10/valoriser-les-contributions-des-entreprises-dans-lecosysteme-wordpress-et-si-on-sinspirait-de-drupal/\";s:3:\"rel\";s:9:\"alternate\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"updated\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"2024-10-06T22:22:15.000+02:00\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"published\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"2024-10-06T22:22:15.000+02:00\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"summary\";a:1:{i:0;a:5:{s:4:\"data\";s:693:\"L’article Valoriser les contributions des entreprises dans l’écosystème WordPress : et si on s’inspirait de… Drupal ? provient de Jean-Baptiste Audras - CTO @ Whodunit & WordPress Core Developer\nDans le cadre de l’affaire WP Engine vs Matt/Automattic/WordPress, le cofondateur de Drupal Dries Buytaert a publié un article qui m’a interpellé. Cet article ne porte pas spécialement sur le conflit entre Matt et WP Engine, mais plutôt sur l’identification et […]\nL’article Valoriser les contributions des entreprises dans l’écosystème WordPress : et si on s’inspirait de… Drupal ? provient de Jean-Baptiste Audras - CTO @ Whodunit & WordPress Core Developer\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"content\";a:1:{i:0;a:5:{s:4:\"data\";s:13548:\"\n        <p>L’article <a href=\"https://jeanbaptisteaudras.com/2024/10/valoriser-les-contributions-des-entreprises-dans-lecosysteme-wordpress-et-si-on-sinspirait-de-drupal/\">Valoriser les contributions des entreprises dans l&rsquo;écosystème WordPress : et si on s&rsquo;inspirait de… Drupal ?</a> provient de <a href=\"https://jeanbaptisteaudras.com\">Jean-Baptiste Audras - CTO @ Whodunit &amp; WordPress Core Developer</a></p>\n\n<div class=\"wp-block-columns alignwide is-layout-flex wp-container-core-columns-is-layout-1 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:100%\">\n<p class=\"has-background-background-color has-background has-large-font-size\">Dans le cadre de l&rsquo;affaire WP Engine <abbr title=\"versus\">vs</abbr> Matt/Automattic/WordPress, le cofondateur de Drupal Dries Buytaert a <a href=\"https://dri.es/solving-the-maker-taker-problem\">publié un article qui m&rsquo;a interpellé</a>.</p>\n</div>\n</div>\n\n\n\n<p>Cet article ne porte pas spécialement sur le conflit entre Matt et WP&nbsp;Engine, mais plutôt sur l&rsquo;identification et la valorisation des entreprises contribuant à un écosystème open-source. <br>C&rsquo;était tout de même le point de départ <em>public</em> du conflit.</p>\n\n\n\n<p>Dans cet article, Dries évoque le concept de <span lang=\"en\" dir=\"ltr\" class=\"lang-attribute\"><em>Maker-Taker</em></span> pour identifier les entreprises qui ne font que profiter du système et celles qui y contribuent. Depuis 10 ans, Drupal a entrepris une action de valorisation des <em><span lang=\"en\" dir=\"ltr\" class=\"lang-attribute\">Makers</span></em> au sein de l&rsquo;écosystème, en mettant en avant de manière très directe ces entreprises à la fois sur les sites de l&rsquo;écosystème et lors des événements.</p>\n\n\n\n<div class=\"wp-block-columns alignwide is-layout-flex wp-container-core-columns-is-layout-2 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:66.66%\">\n<p>Il faut noter une différence majeure dans le système de <em><bdo lang=\"en\" dir=\"ltr\">credit</bdo></em> des écosystèmes WordPress et Drupal pour reconnaitre l&rsquo;effort de contribution : </p>\n\n\n\n<p class=\"has-large-font-size\">Même si WordPress pousse les entreprises à contribuer via l&rsquo;initiative <em><bdo lang=\"en\" dir=\"ltr\">Five for the Future</bdo></em>, notre projet open-source ne reconnait en réalité officiellement que les contributions individuelles et pas celles des entreprises.</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:33.33%\"></div>\n</div>\n\n\n\n<p>Avant de pouvoir envisager de prendre des « mesures » contre les entreprises qui sont davantage des <em><bdo lang=\"en\" dir=\"ltr\">takers</bdo></em> que des <em><bdo lang=\"en\" dir=\"ltr\">makers</bdo></em> –&nbsp;et cette décision reste à discuter&nbsp;– il nous faut déjà pouvoir identifier formellement les entreprises qui contribuent réellement.</p>\n\n\n\n<p>Je vais pousser l&rsquo;exemple au niveau du développement du cœur du <abbr title=\"content management system\"><bdo lang=\"en\" dir=\"ltr\">CMS</bdo></abbr>, mais cela s&rsquo;applique potentiellement à tout type de contribution. Les contributions <em><bdo lang=\"en\" dir=\"ltr\">Core</bdo></em> constituent cependant le noyau central du système de contribution de WP, c&rsquo;est donc intéressant de commencer par là, même si ça s&rsquo;applique potentiellement à toutes les équipes de contribution.</p>\n\n\n\n<h2 class=\"wp-block-heading alignwide\" style=\"font-style:normal;font-weight:300\">L&rsquo;approche de Drupal&nbsp;: gérer les crédits des entreprises directement dans les messages de commit</h2>\n\n\n\n<p>Chez nous, seuls les <strong>individus</strong> sont crédités dans les messages de commit.</p>\n\n\n\n<p>Les comptes WordPress officiels des entreprises éventuellement présents dans certains commits sont manuellement triés lors de la sortie de chaque version, et sont systématiquement éliminés de la liste des crédits de chaque version. Seuls les comptes des individus apparaissent.</p>\n\n\n\n<p>C&rsquo;est une différence majeure par rapport au système de contribution de Drupal qui fait l&rsquo;inverse en reconnaissant directement dans les messages de commits à la fois l&rsquo;individu, sa société et même le cas échéant le client dans le cadre duquel l&rsquo;évolution ou le bug a été remonté.</p>\n\n\n\n<p>Exemple de message de commit chez Drupal :</p>\n\n\n\n<pre class=\"wp-block-code alignwide has-background-color has-primary-background-color has-text-color has-background has-link-color wp-elements-42359ffa5cbd8d2d0ec2cbcc4d27f729\"><code lang=\"bash\" class=\"language-bash\">$ git commit -am \"Issue #42 by Sam@Acquia, Megan, Tim*Pfizer: fixed performance bug.\"</code></pre>\n\n\n\n<p>Dans cet exemple, sont crédités : Sam (individu) de l&rsquo;agence Acquia (employeur de Sam), Megan (individu), Tim (individu) et Pfizer (le client associé à Tim, qui a remonté le bug).</p>\n\n\n\n<figure data-wp-context=\"{&quot;imageId&quot;:&quot;6703ff714099d&quot;}\" data-wp-interactive=\"core/image\" class=\"wp-block-image size-large is-resized wp-lightbox-container\"><img width=\"1024\" height=\"576\" data-wp-init=\"callbacks.setButtonStyles\" src=\"https://jeanbaptisteaudras.com/2019/wp-content/uploads/2024/10/certified-partner-contributions-1920w-1024x576.png\" alt=\"\" class=\"wp-image-145118\" style=\"width:610px;height:auto\" //><button class=\"lightbox-trigger\" type=\"button\" aria-label=\"Agrandir l‘image\" data-wp-init=\"callbacks.initTriggerButton\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\">Diapositive provenant d&rsquo;un <em><bdo lang=\"en\" dir=\"ltr\">DrupalCon</bdo></em> mettant en valeur les principaux contributeur·ices du projet, ainsi que leur employeur respectif.</figcaption></figure>\n\n\n\n<p style=\"font-size:16px\">Source : <a href=\"https://dri.es/a-method-for-giving-credit-to-organizations-that-contribute-code-to-open-source\"><em><bdo lang=\"en\" dir=\"ltr\">A method for giving credit to organizations that contribute code to Open Source</bdo></em></a></p>\n\n\n\n<div style=\"height:97px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n\n\n\n<p class=\"has-large-font-size\">C’est intéressant.</p>\n\n\n\n<div class=\"wp-block-columns alignwide is-layout-flex wp-container-core-columns-is-layout-3 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-vertically-aligned-center is-layout-flow wp-block-column-is-layout-flow\">\n<figure data-wp-context=\"{&quot;imageId&quot;:&quot;6703ff71414fc&quot;}\" data-wp-interactive=\"core/image\" class=\"wp-block-image size-large wp-lightbox-container\"><img width=\"1200\" height=\"1200\" data-wp-init=\"callbacks.setButtonStyles\" src=\"https://jeanbaptisteaudras.com/2019/wp-content/uploads/2023/08/wp63-contributions-company.svg\" alt=\"\" class=\"wp-image-145070\" style=\"object-fit:cover\" //><button class=\"lightbox-trigger\" type=\"button\" aria-label=\"Agrandir l‘image\" data-wp-init=\"callbacks.initTriggerButton\">\n			\n				\n			\n		</button></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-vertically-aligned-center is-layout-flow wp-block-column-is-layout-flow\">\n<p>C&rsquo;est pour avoir ces informations sur la contribution des entreprises dans WP que je sort régulièrement mes statistiques comprenant des graphiques indiquant l&rsquo;implication des sociétés sur les versions majeures de WP, et annuellement dans les articles <em><bdo lang=\"en\" dir=\"ltr\">« Year in Core »</bdo></em>.</p>\n\n\n\n<p>Exemples : </p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://jeanbaptisteaudras.com/2023/08/contribution-stats-for-wordpress-6-3-lionel/#company\">Credits pour WP 6.3</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2024/01/11/a-year-in-core-2023/#contributions-by-company\">A Year in Core 2023</a></li>\n</ul>\n\n\n\n<p>Mais ces stats sont très limitées&nbsp;: elles ne sont qu&rsquo;un <bdo lang=\"en\" dir=\"ltr\">scraping</bdo> des contributions individuelles faites par des personnes ayant indiqué un employeur sur leur profil WordPress.org.</p>\n\n\n\n<p>D&rsquo;une part il y a une marge d&rsquo;erreur liée au <bdo lang=\"en\" dir=\"ltr\">scraping</bdo>, d&rsquo;autre part les gens ont une fâcheuse tendance à changer de boîte de temps à autre… et leurs contributions passées sont alors intégralement rattachées à leur boîte <em>actuelle</em>.</p>\n</div>\n</div>\n\n\n\n<p>Je pense qu&rsquo;il est important de connaitre le volume de contribution réel de chaque entreprise, afin de pouvoir mettre cela en valeur, comme le fait l&rsquo;écosystème Drupal.</p>\n\n\n\n<p>Mais comment peut-on le faire tout en utilisant les mécanismes actuellement disponibles sur WP&nbsp;?</p>\n\n\n\n<h2 class=\"wp-block-heading alignwide\" style=\"font-style:normal;font-weight:300\">Proposition d’une approche alternative pour WordPress, basée sur l&rsquo;initiative <em><bdo lang=\"en\" dir=\"ltr\">Five for the Future</bdo></em></h2>\n\n\n\n<div class=\"wp-block-columns alignwide is-layout-flex wp-container-core-columns-is-layout-4 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-vertically-aligned-center is-layout-flow wp-block-column-is-layout-flow\">\n<figure data-wp-context=\"{&quot;imageId&quot;:&quot;6703ff7142319&quot;}\" data-wp-interactive=\"core/image\" class=\"wp-block-image size-large wp-lightbox-container\"><img width=\"1024\" height=\"874\" data-wp-init=\"callbacks.setButtonStyles\" src=\"https://jeanbaptisteaudras.com/2019/wp-content/uploads/2024/10/Capture-decran-2024-10-05-a-23.03.50-1024x874.png\" alt=\"\" class=\"wp-image-145159\" //><button class=\"lightbox-trigger\" type=\"button\" aria-label=\"Agrandir l‘image\" data-wp-init=\"callbacks.initTriggerButton\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\">Flux de contributions sur une page de profil WordPress.org individuelle.</figcaption></figure>\n</div>\n\n\n\n<div class=\"wp-block-column is-vertically-aligned-center is-layout-flow wp-block-column-is-layout-flow\">\n<p>Il n&rsquo;est pas forcément nécessaire d&rsquo;agir directement dans les messages de commits comme chez Drupal, mais on peut le faire via les <em><bdo lang=\"en\" dir=\"ltr\"><a href=\"https://wordpress.org/five-for-the-future/pledges/?order=contributors\">Pledges</a></bdo></em> qui existent déjà dans l&rsquo;initiative <em><bdo lang=\"en\" dir=\"ltr\"><a href=\"https://wordpress.org/five-for-the-future/\">Five for the Future</a></bdo></em>.</p>\n\n\n\n<p>Comme nous connaissons l&#8217;employeur de chaque individu ayant fait une contribution (à partir du moment où le champ correspondant est renseigné), nous pouvons sans doute « facilement » remonter automatiquement sur la page des organisations la liste complète des contributions effectuées par des personnes qui sont sponsorisées ou appartiennent à l&rsquo;entreprise, au moment où la contribution a eu lieu.</p>\n\n\n\n<p>Et nous pouvons donc l&rsquo;archiver sous la forme d&rsquo;un flux similaire à celui des profils individuels.</p>\n</div>\n</div>\n\n\n\n<p>Ainsi, il serait bien plus simple de connaitre les contributions réelles de chaque entreprise, et surtout : cela résoudrait le problème connu des personnes qui changent d&rsquo;entreprise au fil du temps et dont les contributions ne semblent être rattachées qu&rsquo;à leur entreprise/sponsor actuel.</p>\n\n\n\n<p>Un sujet qui m&rsquo;a d&rsquo;ailleurs déjà été remonté par exemple par Peter Wilson ou encore Johny Harris par le passé&nbsp;: lorsque les gens changent d&rsquo;entreprise, cela fausse les contributions de l&rsquo;ancienne entreprise comme de la nouvelle, en attribuant le volume de contribution de la personne à son entreprise actuelle.</p>\n\n\n\n<p>Cela permettrait ainsi de conserver un historique de contributions sur la page de l&rsquo;organisation tout en permettant à l&rsquo;individu qui est l&rsquo;auteur·ice de la contribution de pouvoir décider d&rsquo;attribuer ses nouvelles contribution à son employeur actuel.</p>\n\n\n\n<div class=\"wp-block-columns alignwide is-layout-flex wp-container-core-columns-is-layout-5 wp-block-columns-is-layout-flex\">\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:66.66%\">\n<p class=\"has-large-font-size\">Quand on aura des statistiques plus précises, il sera déjà plus simple de voir quelles sont les entreprises réellement impliquées dans la contribution à notre écosystème, et par déduction de voir celles qui ne contribuent pas, ou peu. Aujourd&rsquo;hui ce n&rsquo;est pas vraiment possible d&rsquo;avoir cette information, publiquement.</p>\n</div>\n\n\n\n<div class=\"wp-block-column is-layout-flow wp-block-column-is-layout-flow\" style=\"flex-basis:33.33%\"></div>\n</div>\n\n\n\n<p>Même avec cette proposition, ça restera un peu moins précis que le système mis en place par Drupal, mais c&rsquo;est quelque chose que l&rsquo;on peut mettre en place sans trop de difficulté et à court terme.</p>\n\n\n\n<p>Je suis évidemment disponible pour mettre en place les premières briques de cette implémentation avec l&rsquo;équipe <bdo lang=\"en\" dir=\"ltr\">Make/Meta</bdo>.</p>\n<p>L’article <a href=\"https://jeanbaptisteaudras.com/2024/10/valoriser-les-contributions-des-entreprises-dans-lecosysteme-wordpress-et-si-on-sinspirait-de-drupal/\">Valoriser les contributions des entreprises dans l&rsquo;écosystème WordPress : et si on s&rsquo;inspirait de… Drupal ?</a> provient de <a href=\"https://jeanbaptisteaudras.com\">Jean-Baptiste Audras - CTO @ Whodunit &amp; WordPress Core Developer</a></p>\n\n    \";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:4:\"type\";s:4:\"html\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"author\";a:1:{i:0;a:6:{s:4:\"data\";s:46:\"\n            \n                                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"name\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"Jb\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:6:\"source\";a:1:{i:0;a:6:{s:4:\"data\";s:67:\"\n                    \n                            \n                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:2:{s:2:\"id\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"https://jeanbaptisteaudras.com/wordpress/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"Jb Audras\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}}}}}s:4:\"type\";i:512;s:7:\"headers\";O:48:\"WpOrg\\Requests\\Utility\\CaseInsensitiveDictionary\":1:{s:7:\"\0*\0data\";a:11:{s:6:\"server\";s:12:\"nginx/1.27.0\";s:4:\"date\";s:29:\"Wed, 20 Nov 2024 13:49:59 GMT\";s:12:\"content-type\";s:20:\"application/atom+xml\";s:12:\"x-powered-by\";s:10:\"PHP/8.0.30\";s:13:\"last-modified\";s:29:\"Fri, 01 Dec 2023 22:13:18 GMT\";s:4:\"etag\";s:34:\"\"c11b85e08f9a55c369b83cdc4e5e720f\"\";s:4:\"link\";s:57:\"<https://rss.wpfr.net/wp-json/>; rel=\"https://api.w.org/\"\";s:13:\"cache-control\";s:35:\"no-cache, no-store, must-revalidate\";s:6:\"pragma\";s:8:\"no-cache\";s:7:\"expires\";s:1:\"0\";s:25:\"strict-transport-security\";s:16:\"max-age=63072000\";}}s:5:\"build\";s:14:\"20211220193300\";}', 'off');
