(29, 13, 'technicalDefinitions', '[{\"type\":\"http\",\"name\":\"real_cookie_banner*\",\"host\":\".mg-palmproperties.local\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Identifiant unique pour le consentement, mais pas pour le visiteur du site web. Hachure de r\\u00e9vision pour les param\\u00e8tres de la banni\\u00e8re des cookies (textes, couleurs, caract\\u00e9ristiques, groupes de services, services, bloqueurs de contenu, etc.) ID des services et groupes de services autoris\\u00e9s.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner*-tcf\",\"host\":\".mg-palmproperties.local\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Consentements recueillis dans le cadre du TCF et stock\\u00e9s dans le format TC String, y compris les fournisseurs du TCF, les objectifs, les objectifs sp\\u00e9ciaux, les caract\\u00e9ristiques et les caract\\u00e9ristiques sp\\u00e9ciales.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner*-gcm\",\"host\":\".mg-palmproperties.local\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Les consentements relatifs aux types de consentement (finalit\\u00e9s) collect\\u00e9s dans le cadre du mode de consentement de Google sont stock\\u00e9s pour tous les services compatibles avec le mode de consentement de Google.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner-test\",\"host\":\".mg-palmproperties.local\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Cookie mis en place pour tester la fonctionnalit\\u00e9 des cookies HTTP. Il est supprim\\u00e9 imm\\u00e9diatement apr\\u00e8s le test.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*\",\"host\":\"http:\\/\\/mg-palmproperties.local\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Identifiant unique pour le consentement, mais pas pour le visiteur du site web. Hachure de r\\u00e9vision pour les param\\u00e8tres de la banni\\u00e8re des cookies (textes, couleurs, caract\\u00e9ristiques, groupes de services, services, bloqueurs de contenu, etc.) Identifiant des services et des groupes de services autoris\\u00e9s. N\'est stock\\u00e9 que jusqu\'\\u00e0 ce que le consentement soit document\\u00e9 sur le serveur du site web.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*-tcf\",\"host\":\"http:\\/\\/mg-palmproperties.local\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Les consentements recueillis dans le cadre du TCF sont stock\\u00e9s dans le format TC String, y compris les fournisseurs du TCF, les objectifs, les objectifs sp\\u00e9ciaux, les caract\\u00e9ristiques et les caract\\u00e9ristiques sp\\u00e9ciales. Ils ne sont stock\\u00e9s que jusqu\'\\u00e0 ce que le consentement soit document\\u00e9 sur le serveur du site web.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*-gcm\",\"host\":\"http:\\/\\/mg-palmproperties.local\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Les consentements recueillis dans le cadre du mode de consentement de Google sont stock\\u00e9s dans les types de consentement (finalit\\u00e9s) pour tous les services compatibles avec le mode de consentement de Google. Il n\'est stock\\u00e9 que jusqu\'\\u00e0 ce que le consentement soit document\\u00e9 sur le serveur du site web.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner-consent-queue*\",\"host\":\"http:\\/\\/mg-palmproperties.local\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Mise en cache locale de la s\\u00e9lection dans une banni\\u00e8re de cookies jusqu\'\\u00e0 ce que le serveur documente le consentement ; documentation p\\u00e9riodique ou tentative de changement de page si le serveur n\'est pas disponible ou surcharg\\u00e9.\"}]'),
