INSERT INTO `mgpp_term_taxonomy` (`term_taxonomy_id`, `term_id`, `taxonomy`, `description`, `parent`, `count`) VALUES
(1, 1, 'category', '', 0, 0),
(2, 2, 'rcb-cookie-group', 'Les services essentiels sont nécessaires à la fonctionnalité de base du site web. Ils ne contiennent que des services techniquement nécessaires. Il n\'est pas possible de s\'opposer à ces services.', 0, 1),
(3, 3, 'rcb-cookie-group', 'Les services fonctionnels sont nécessaires pour fournir des caractéristiques allant au-delà de la fonctionnalité essentielle, telles que des polices plus jolies, la lecture de vidéos ou des caractéristiques interactives du web 2.0. Les contenus provenant, par exemple, de plateformes vidéo et de plateformes de médias sociaux sont bloqués par défaut et peuvent faire l\'objet d\'un consentement. Si le service est accepté, ce contenu est chargé automatiquement sans autre consentement manuel.', 0, 0),
(4, 4, 'rcb-cookie-group', 'Les services statistiques sont nécessaires pour collecter des données pseudonymes sur les visiteurs du site web. Ces données nous permettent de mieux comprendre les visiteurs et d\'optimiser le site web.', 0, 0),
(5, 5, 'rcb-cookie-group', 'Les services de marketing sont utilisés par nous et par des tiers pour suivre le comportement des visiteurs individuels (sur plusieurs pages), analyser les données collectées et, par exemple, afficher des publicités personnalisées. Ces services nous permettent de suivre les visiteurs sur plusieurs sites web.', 0, 0),
(6, 6, 'language', 'a:3:{s:6:\"locale\";s:5:\"fr_FR\";s:3:\"rtl\";i:0;s:9:\"flag_code\";s:2:\"fr\";}', 0, 8),
